import javax.swing.*;
import javax.swing.table.DefaultTableModel;
import java.awt.*;
import java.nio.file.*;
import java.util.*;
import java.util.function.*;

/** Controls evolutionary islands and opens consistent checkpoint copies for inspection. */
public final class BatchPanel extends JPanel {
    private final Supplier<Simulation> source;
    private final Consumer<Simulation> open;
    private WorldBatch batch;
    private final DefaultTableModel model=new DefaultTableModel(new String[]{"World","Seed","State","Simulated seconds","Prey","Hunters","Island G","Detail"},0){public boolean isCellEditable(int r,int c){return false;}};
    private final JTable table=new JTable(model);
    private final JLabel note=new JLabel("Every island copies the same top genomes per role, then evolves independently with its own seed.");
    private final JSpinner worlds=new JSpinner(new SpinnerNumberModel(4,1,32,1)),workers=new JSpinner(new SpinnerNumberModel(Math.min(4,Runtime.getRuntime().availableProcessors()),1,8,1)),duration=new JSpinner(new SpinnerNumberModel(1800,1,86400,60)),sample=new JSpinner(new SpinnerNumberModel(30,1,3600,1)),checkpoint=new JSpinner(new SpinnerNumberModel(300,1,3600,1));
    private final JTextField firstSeed=new JTextField("10001",15);
    private WorldConfig settings;
    public BatchPanel(Supplier<Simulation> source,Consumer<Simulation> open){
        super(new BorderLayout(12,12));this.source=source;this.open=open;settings=source.get().settings();setBorder(BorderFactory.createEmptyBorder(16,16,16,16));JPanel form=new JPanel(new GridLayout(0,6,8,8));Object[][] fields={{"Worlds",worlds},{"CPU workers",workers},{"Seconds per world",duration},{"First seed",firstSeed},{"CSV interval (s)",sample},{"Checkpoint interval (s)",checkpoint}};for(Object[] f:fields){form.add(new JLabel((String)f[0]));form.add((Component)f[1]);UiTheme.tip((JComponent)f[1],"Configure "+((String)f[0]).toLowerCase()+". Seeds are consecutive; simulated biology remains fixed at 60 ticks/second.");}JPanel top=new JPanel(new BorderLayout(8,10));top.add(note,BorderLayout.NORTH);top.add(form);add(top,BorderLayout.NORTH);add(new JScrollPane(table));table.setRowHeight(30);table.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);
        JPanel actions=new JPanel(new FlowLayout(FlowLayout.LEFT));actions.add(button("World settings…","Customize the common settings for new islands.",()->{var choice=WorldSettingsPanel.edit(this,settings,Long.parseLong(firstSeed.getText().trim()),"Island settings",false);if(choice!=null){settings=choice.config();firstSeed.setText(Long.toString(choice.seed()));}}));
        actions.add(button("Start islands…","Choose an output folder. Source genomes, manifests, incremental CSVs and rolling checkpoints are saved per world.",this::start));actions.add(button("Stop selected","Request a checkpoint and stop at the next tick.",()->{if(batch!=null&&table.getSelectedRow()>=0)batch.stop(table.getSelectedRow()+1);}));actions.add(button("Breed / resume selected","Continue a stopped world, or breed the next population after generation inspection.",()->{if(batch!=null&&table.getSelectedRow()>=0)batch.resume(table.getSelectedRow()+1);}));actions.add(button("Open checkpoint","Open a saved checkpoint in the main dish, paused. A running worker continues its independent copy.",this::inspect));actions.add(button("Stop all","Save checkpoints and stop all current islands.",()->{if(batch!=null)batch.stopAll();}));add(actions,BorderLayout.SOUTH);UiTheme.apply(this);
        javax.swing.Timer timer=new javax.swing.Timer(750,e->refresh());addHierarchyListener(e->{if(isShowing())timer.start();else timer.stop();});
    }
    private JButton button(String text,String help,Runnable action){JButton b=new JButton(text);UiTheme.tip(b,help);b.addActionListener(e->{try{action.run();}catch(Exception ex){JOptionPane.showMessageDialog(this,ex.getMessage(),"Background worlds",JOptionPane.ERROR_MESSAGE);}});return b;}
    private void start(){if(batch!=null&&batch.busy())throw new IllegalStateException("Stop the existing islands before starting a new batch.");for(JSpinner s:new JSpinner[]{worlds,workers,duration,sample,checkpoint})try{s.commitEdit();}catch(Exception ex){throw new IllegalArgumentException("Invalid batch number",ex);}Simulation s=source.get();EnumMap<Simulation.Species,java.util.List<Simulation.Genome>> pools=new EnumMap<>(Simulation.Species.class);for(var role:Simulation.Species.values())pools.put(role,s.topGenomes(role));if(settings.initialPrey>0&&pools.get(Simulation.Species.PREY).isEmpty()||settings.hunters&&settings.initialHunters>0&&pools.get(Simulation.Species.PREDATOR).isEmpty())throw new IllegalStateException("No source genomes for a requested role. Run that role in the live world first, or disable it in island settings.");JFileChooser c=new JFileChooser();c.setFileSelectionMode(JFileChooser.DIRECTORIES_ONLY);if(c.showSaveDialog(this)!=JFileChooser.APPROVE_OPTION)return;if(batch!=null)batch.close();Path dir=c.getSelectedFile().toPath().resolve("islands-"+System.currentTimeMillis());batch=new WorldBatch(settings,pools,Long.parseLong(firstSeed.getText().trim()),number(worlds),number(workers),number(duration),number(sample),number(checkpoint),dir,"Top "+s.config.parentPool+" per role from seed "+(s.seedKnown?s.seed:"unrecorded")+", elapsed ticks "+s.elapsedTicks+", source deepest G "+s.generation);note.setText("Output: "+dir.toAbsolutePath());refresh();}
    private int number(JSpinner s){return ((Number)s.getValue()).intValue();}
    private void refresh(){if(batch==null)return;int selected=table.getSelectedRow();model.setRowCount(0);for(var s:batch.statuses())model.addRow(new Object[]{s.index(),s.seed(),s.state(),String.format("%.1f",s.seconds()),s.prey(),s.hunters(),s.generation(),s.detail()});if(selected>=0&&selected<model.getRowCount())table.setRowSelectionInterval(selected,selected);}
    private void inspect(){if(batch==null||table.getSelectedRow()<0)return;Path path=batch.statuses().get(table.getSelectedRow()).checkpoint();if(path==null)throw new IllegalStateException("No checkpoint is ready yet.");new SwingWorker<Simulation,Void>(){protected Simulation doInBackground()throws Exception{return WorldIO.read(path);}protected void done(){try{open.accept(get());}catch(Exception ex){JOptionPane.showMessageDialog(BatchPanel.this,ex.getMessage(),"Checkpoint",JOptionPane.ERROR_MESSAGE);}}}.execute();}
}
